'use strict';
const vals=[-22.1,-22,-22.2,-22.1,-21.9,-22,-22.1,-21.5,-20.7,-19.4,-17.8,-17.1,-16.5,-15.9,-15.3,-14.8,-14.2,-13.9,-14.4,-16.6,-18.4,-19.3,-19.9,-20.3,-20.5];
function chart(){const x=i=>44+i*23.1,y=v=>200-(v+24)*15;return `<svg viewBox="0 0 640 245" role="img" aria-label="Temperatura de aire de C-07: pico de menos 13,9 grados a las 06:25; 50 minutos por encima de menos 18 grados"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#46b7a0" stop-opacity=".22"/><stop offset="1" stop-color="#46b7a0" stop-opacity="0"/></linearGradient></defs>${[-24,-21,-18,-15,-12].map(v=>`<line x1="44" x2="600" y1="${y(v)}" y2="${y(v)}" stroke="${v===-18?'#d77989':'#e8eef0'}" stroke-dasharray="${v===-18?'5 5':'0'}"/><text x="0" y="${y(v)+4}" fill="#7a8c98" font-size="11">${v}°</text>`).join('')}<path d="M44,200 ${vals.map((v,i)=>`L${x(i)},${y(v)}`).join(' ')} L600,200 Z" fill="url(#area)"/><path d="${vals.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ')}" fill="none" stroke="#248f81" stroke-width="2.5" stroke-linejoin="round"/><circle cx="${x(17)}" cy="${y(-13.9)}" r="5" fill="#fff" stroke="#bc4058" stroke-width="2.5"/><rect x="${x(17)-39}" y="${y(-13.9)-34}" width="78" height="23" fill="#fff0f2" rx="4"/><text x="${x(17)}" y="${y(-13.9)-18}" text-anchor="middle" font-size="12" font-weight="600" fill="#ad3449">−13,9 °C</text>${[0,6,12,18,24].map((n,i)=>`<text x="${x(n)}" y="228" font-size="11" fill="#7a8c98" text-anchor="middle">${['05:00','05:30','06:00','06:30','07:00'][i]}</text>`).join('')}</svg>`}
document.getElementById('initial-chart').innerHTML=chart();
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>Number(v).toLocaleString('es-ES',{maximumFractionDigits:1});
const normalize=v=>String(v).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const coldPrompt='Cuando una cámara supere −18 °C durante más de 15 minutos, identifica los lotes y palés afectados, consulta su trazabilidad, pide aprobación a Calidad para retenerlos y prepara un informe de incidencia.';
const complaintPrompt='Cuando llegue una reclamación de un cliente, extrae el lote y el motivo, consulta la trazabilidad, pide aprobación a Calidad y prepara un borrador de investigación y respuesta.';
const dailyPrompt='Prepara el parte diario de planta, prioriza las anomalías y reúne las evidencias para el jefe de turno.';
const exampleEmail='From: Quality team <quality@retailer-uk.example>\nTo: Quality team <quality@demo.example>\nSubject: Consumer complaint · UKC-44718\n\nDear Quality Team,\n\nA consumer reported a stone of approximately 8 mm in a bag of Garden Peas 1kg.\n\nLot: L26-231-FUS-GUI-01\nBest before: 08/2028\nConsumer reference: UKC-44718\n\nPlease investigate the affected batch and provide an investigation report within five working days. We will send the sample for examination.\n\nKind regards,\nCustomer Quality Team';
const steps={cold:[['sensor','Analizar la señal','Lectura de temperatura y regla configurada'],['trace','Trazar los lotes','Origen, stock y expediciones relacionadas'],['human','Pedir aprobación a Calidad','La ejecución espera una decisión'],['hold','Aplicar la retención simulada','Solo los palés incluidos en la propuesta'],['file','Preparar el expediente','Evidencias, decisión y tareas pendientes']],complaint:[['mail','Estructurar la reclamación','Lote, defecto y referencia del cliente'],['trace','Recuperar trazabilidad','Stock disponible y producto expedido'],['human','Revisar con Calidad','Evaluar la propuesta de contención'],['hold','Retener stock disponible','Acción simulada sobre 2 palés'],['file','Preparar investigación y respuesta','Borrador sujeto a revisión; sin envío']],daily:[['sensor','Leer el parte de planta','11 equipos con lecturas sintéticas'],['trace','Ordenar las anomalías','4 críticas y 3 avisos según reglas demo'],['file','Preparar el parte diario','Evidencias para el jefe de turno']]};
const glyphs={sensor:'⌁',trace:'◇',human:'◎',hold:'▣',file:'≡',mail:'✉'};
let S={view:'operations',guide:false,prompt:coldPrompt,draft:null,workflow:null,run:null,complaint:null,question:'',answer:null,roi:{cases:40,before:45,after:15}};
let runToken=0,toastTimer;
const startHTML=$('#main').innerHTML;
const titles={operations:'Operaciones',studio:'Workflow Studio',case:'Reclamaciones',knowledge:'Conocimiento',platform:'Prodigy'};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3400)}
function modal(title,html){$('#modal').innerHTML=`<div class="modal-head"><h2>${esc(title)}</h2><button class="close" data-action="close-modal" aria-label="Cerrar">×</button></div>${html}`;if(!$('#modal').open)$('#modal').showModal()}
function head(eyebrow,title,desc,action=''){return `<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>${action}</div>`}
function guide(){if(!S.guide)return '';const lines={operations:'<strong>1 / 5 · Apertura · 1 minuto.</strong> “Imaginad que recibís esta alarma al comenzar el turno. Vamos a reunir la evidencia y preparar una decisión. Todos los datos son ficticios.” Pulsa <b>Crear un workflow</b>.',studio:'<strong>2 / 5 · Pieza central · 4 minutos.</strong> Pulsa <b>Generar workflow</b>, revisa los pasos, <b>Guardar workflow</b> y <b>Simular alarma C-07</b>. Abre un lote y detente en la aprobación. “Calidad mantiene la decisión.”',case:'<strong>3 / 5 · Reclamaciones · 2 minutos.</strong> Pulsa <b>Analizar reclamación</b>. Muestra las expediciones y la hipótesis aún sin confirmar. Aprueba la retención de 2 palés para ver el borrador. “El equipo revisa antes de responder al cliente.”',knowledge:'<strong>4 / 5 · Conocimiento · 1 minuto.</strong> Pulsa la pregunta sobre liberar un lote y abre su fuente. Prueba una pregunta fuera del catálogo. “Si no hay evidencia, el asistente debe reconocerlo.”',platform:'<strong>5 / 5 · Cierre · 2 minutos.</strong> Muestra qué aporta la plataforma y qué requiere el piloto. “Elegimos un caso, una planta y una medida de éxito. ¿Empezamos con Calidad y Sistemas?”'};return `<div class="guide-bar"><button class="close" data-action="toggle-guide" aria-label="Ocultar guion">×</button>${lines[S.view]}</div>`}
function go(view){if(!titles[view])return;S.view=view;location.hash=view;render();window.scrollTo({top:0,behavior:'instant'})}
function render(){const el=$('#main');el.innerHTML=guide()+({operations:operations,studio:studio,case:caseView,knowledge:knowledge,platform:platform}[S.view])();$$('[data-nav]').forEach(b=>{b.classList.toggle('active',b.dataset.nav===S.view);b.setAttribute('aria-current',b.dataset.nav===S.view?'page':'false')});$('#crumb').textContent=titles[S.view];$('#presenter').textContent=S.guide?'Ocultar guion':'Guion';}
function operations(){const dashboard=S.run?.status==='approved'?startHTML.replace('01<small>pendiente</small>','00<small>pendientes</small>').replace('La aprobación sigue en tus manos','Retención simulada registrada'):startHTML;return dashboard.replace('<div class="chart" id="initial-chart"></div>',`<div class="chart">${chart()}</div>`)+`<div class="section-title"><h2>Tu recorrido de hoy</h2><p>Explora tres formas de trabajar con Prodigy</p></div><div class="events"><article class="card event"><span class="event-icon">⌁</span><div><h3>Responder a la alarma C-07</h3><p>Seis lotes, una decisión coordinada.</p><button class="text-button" data-action="open-studio">Crear el workflow</button></div></article><article class="card event"><span class="event-icon">✉</span><div><h3>Investigar una reclamación</h3><p>Del correo en inglés al expediente.</p><button class="text-button" data-action="open-case">Abrir reclamación</button></div></article><article class="card event"><span class="event-icon">≡</span><div><h3>Consultar un procedimiento</h3><p>Respuestas que permiten abrir la fuente.</p><button class="text-button" data-action="open-knowledge">Preguntar a Calidad</button></div></article></div><div class="section-title"><h2>Parte de planta</h2><button class="text-button" data-action="daily-report">Ver los 11 equipos</button></div><div class="card table-scroll"><table class="trace-table"><thead><tr><th>Equipo</th><th>Lectura simulada</th><th>Referencia demo</th><th>Prioridad</th></tr></thead><tbody>${DEMO_DATA.machines.filter(m=>['TUN-1','OPT-2','NH3-C2','DM-1'].includes(m.code)).map(m=>machineRow(m)).join('')}</tbody></table></div>`}
function machineRow(m){const severe=['ESC-3','OPT-2','NH3-C2','DM-1'].includes(m.code),warn=['TUN-1','EV-SIL3','ENV-5'].includes(m.code);return `<tr><td><b>${m.code}</b><small>${esc(m.area)}</small></td><td>${fmt(m.reading)} ${esc(m.unit)}</td><td>${fmt(m.baseline)}</td><td><span class="badge ${severe?'danger':warn?'amber':'good'}">${severe?'Crítica':warn?'Aviso':'Conforme'}</span></td></tr>`}
function nodes(kind,run=null){return steps[kind].map((n,i)=>{let status='';if(run){if(run.status==='no-trigger')status=i===0?'done':'';else if(run.status==='rejected')status=i<2?'done':i===2?'waiting':'';else if(run.status==='approved'||run.status==='complete')status='done';else if(run.status==='pending')status=i<2?'done':i===2?'waiting':'';else status=i<run.step?'done':i===run.step?'running':'';}return `<div class="node ${n[0]==='human'?'node-human':''} ${status}"><span class="node-icon">${glyphs[n[0]]}</span><div><h3>${i+1}. ${n[1]}</h3><p>${n[2]}</p></div><span class="node-status">${status==='done'?'✓':status==='waiting'?'Espera':status==='running'?'···':''}</span></div>`}).join('')}
function studio(){const w=S.draft||S.workflow,r=S.run;if(r)return liveStudio(w,r);return head('WORKFLOW STUDIO / DISEÑO ASISTIDO','Descríbelo. Revísalo. Ejecútalo.','Transforma una instrucción en una secuencia de trabajo visible.')+`<div class="steps-inline"><span class="${!w?'current':''}">1 · Describe</span><span class="${w&&!S.workflow?'current':''}">2 · Revisa y guarda</span><span class="${S.workflow&&!r?'current':''}">3 · Ejecuta</span><span class="${r?'current':''}">4 · Decide</span></div><div class="split"><section class="card padded"><h2>¿Qué quieres que ocurra?</h2><p>Describe el disparador, los pasos y quién debe aprobar.</p><label class="field-label" for="workflow-prompt">Instrucción en lenguaje natural</label><textarea id="workflow-prompt" rows="6" maxlength="1400">${esc(S.prompt)}</textarea><div class="chips"><button class="chip" data-example="cold">Cadena de frío</button><button class="chip" data-example="complaint">Reclamación</button><button class="chip" data-example="daily">Parte diario</button></div><button class="primary full" data-action="generate" ${r?.status==='running'?'disabled':''}>${w?'Regenerar propuesta':'Generar workflow'}</button><p class="hint">Generador de demostración para estos tres escenarios. Revisa la propuesta antes de guardarla.</p>${w?`<hr class="divider"><h3>${esc(w.name)}</h3>${w.kind==='cold'?`<div class="rules-row"><div><label class="field-label" for="threshold">Umbral de aire (°C)</label><input id="threshold" required type="number" min="-25" max="-10" step=".5" value="${w.temp}"></div><div><label class="field-label" for="duration">Más de (minutos)</label><input id="duration" required type="number" min="0" max="120" step="5" value="${w.minutes}"></div></div><p class="hint">Regla ilustrativa. No equivale a una evaluación de temperatura de producto.</p>`:''}<div class="banner">${S.workflow&&!S.draft?'✓ Workflow guardado en esta sesión.':'Propuesta lista para revisar.'} ${w.kind!=='daily'?'La aprobación humana forma parte del flujo.':''}</div><div class="actions"><button class="${S.workflow&&!S.draft?'secondary':'primary'} full" data-action="save-workflow" ${r?.status==='running'?'disabled':''}>${S.workflow&&!S.draft?'Actualizar workflow':'Guardar workflow'}</button>${S.workflow&&!S.draft?`<button class="primary full" data-action="run" ${r?.status==='running'||r?.status==='pending'?'disabled':''}>${w.kind==='cold'?'Simular alarma C-07':w.kind==='complaint'?'Probar con reclamación':'Generar parte diario'}</button><button class="text-button" data-action="export-workflow">Descargar definición JSON</button>`:''}</div>`:''}</section><section class="card"><div class="card-head"><div><h2>${w?esc(w.name):'Tu workflow aparecerá aquí'}</h2><p>${w?`${steps[w.kind].length} pasos · ${w.kind==='daily'?'Lectura y resumen':'Aprobación humana obligatoria'} · Ejecución secuencial`:'Cada paso muestra su función y el control de Calidad.'}</p></div>${w?`<span class="badge ${S.draft?'info':'good'}">${S.draft?'Borrador':'Guardado'}</span>`:''}</div><div class="workflow-board">${w?nodes(w.kind,r):'<div class="empty-board"><div class="empty-symbol">◇ ─ ◎ ─ ▣</div><h3>Primero la intención.<br>Después, un plan revisable.</h3><p>Escribe tu instrucción o utiliza uno de los ejemplos de la izquierda.</p></div>'}</div></section></div>${r?execution(r):''}`}
function parsePrompt(prompt){const p=normalize(prompt).replace(/−/g,'-');if(/reclamacion|complaint|queja/.test(p))return {kind:'complaint',name:'Reclamación · Investigación de calidad',prompt};if(/camara|cadena de frio|temperatura|frigorif/.test(p)){const t=p.match(/(-\d{1,2}(?:[.,]\d+)?)\s*(?:°?\s*c|grados)/),m=p.match(/(\d+)\s*min/);return {kind:'cold',name:'Cadena de frío · Respuesta coordinada',prompt,temp:t?Number(t[1].replace(',','.')):-18,minutes:m?Number(m[1]):15};}if(/parte diario|jefe de turno|estado de planta/.test(p))return {kind:'daily',name:'Planta · Parte diario priorizado',prompt};return null;}
function generate(){if(S.run?.status==='running')return;S.prompt=$('#workflow-prompt').value.trim();const w=parsePrompt(S.prompt);if(!w){toast('Esta demo admite cadena de frío, reclamaciones y parte diario. Elige un ejemplo.');return}if(w.temp!==undefined&&(w.temp< -25||w.temp> -10||w.minutes>120)){toast('Usa un umbral entre −25 y −10 °C y una duración entre 0 y 120 minutos.');return}if(/sin aprob|sin calidad|automaticamente.*bloqu|no.*aprob/.test(normalize(S.prompt)))toast('La propuesta mantiene la aprobación de Calidad para cualquier retención.');S.draft=w;S.workflow=null;S.run=null;runToken++;render()}
function saveWorkflow(){if(S.run?.status==='running')return;let w={...(S.draft||S.workflow)};if(!w.kind)return;if(w.kind==='cold'){const t=$('#threshold'),m=$('#duration');if(!t.reportValidity()||!m.reportValidity())return;w.temp=Number(t.value);w.minutes=Number(m.value)}S.workflow=w;S.draft=null;S.run=null;runToken++;render();toast('Workflow guardado. Ya puedes ejecutarlo en esta sesión.')}
const wait=ms=>new Promise(r=>setTimeout(r,ms));
function logRun(r,msg){r.audit.push({time:new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit',second:'2-digit'}),message:msg})}
async function runWorkflow(){if(!S.workflow||S.draft||['running','pending'].includes(S.run?.status))return;const w=S.workflow;if(w.kind==='complaint'){go('case');analyzeCase(exampleEmail);return}if(w.kind==='daily'){dailyReport();return}const token=++runToken;S.run={kind:'cold',status:'running',step:0,audit:[],threshold:w.temp,duration:w.minutes,id:'SIM-CN-001',decision:null};const r=S.run;logRun(r,`Inicio de ejecución simulada. Regla: > ${w.temp} °C durante más de ${w.minutes} minutos.`);render();await wait(800);if(token!==runToken)return;r.exposure=longestExposure(w.temp);logRun(r,`Serie de aire consultada: pico −13,9 °C; ${r.exposure} minutos consecutivos por encima de ${w.temp} °C (muestras de 5 min).`);if(r.exposure<=w.minutes){r.status='no-trigger';logRun(r,'La condición configurada no se cumple. Sin propuesta de retención.');render();scrollExecution();return}r.step=1;render();await wait(850);if(token!==runToken)return;logRun(r,'Inventario cruzado: 38 palés en C-07, repartidos en 6 lotes. Otros palés del mismo lote se muestran aparte.');r.step=2;r.status='pending';logRun(r,'Propuesta pendiente de aprobación humana. Todavía no se ha aplicado ninguna retención.');render();scrollExecution()}
function scrollExecution(){setTimeout(()=>$('#execution')?.scrollIntoView({behavior:'smooth',block:'start'}),50)}
function lotTable(mode='cold'){const ls=mode==='cold'?DEMO_DATA.lots.filter(l=>l.exposed):[DEMO_DATA.lots.find(l=>l.id==='L26-231-FUS-GUI-01')];return `<div class="table-scroll"><table class="trace-table"><thead><tr><th>Lote / producto</th><th>${mode==='cold'?'En C-07':'En SIL-3'}</th><th>Otros destinos</th><th>Genealogía</th></tr></thead><tbody>${ls.map(l=>`<tr><td><button class="lot-link" data-lot="${l.id}">${l.id}</button><small>${esc(l.product)}</small></td><td><b>${mode==='cold'?l.exposed:2} palés</b></td><td>${mode==='cold'?`${l.produced-l.exposed} palés fuera de C-07`:'20 palés ya expedidos'}<small>${l.produced} producidos en total</small></td><td><button class="text-button" data-lot="${l.id}">Ver traza ↗</button></td></tr>`).join('')}</tbody></table></div>`}
function audit(r){return `<section class="card padded"><h2>Registro de la ejecución</h2><p class="small-note">Evidencia de esta sesión · ${r.id}</p><ol class="timeline">${r.audit.map(a=>`<li><time>${a.time}</time>${esc(a.message)}</li>`).join('')}</ol>${r.status!=='running'?'<button class="text-button" data-action="download-audit">Descargar registro JSON</button>':''}</section>`}
function approval(r){const cold=r.kind==='cold';return `<section class="approval"><div class="eyebrow">CONTROL HUMANO / PENDIENTE</div><h2>Calidad tiene la última palabra</h2><p>${cold?'Se propone retener únicamente los palés presentes en C-07 durante el episodio.':'Se propone retener los 2 palés del lote aún disponibles en SIL-3. Los 20 expedidos requieren una evaluación separada.'} La temperatura de aire o una reclamación, por sí solas, no determinan el destino del producto.</p><div class="approval-summary"><div><strong>${cold?'38':'2'}</strong><span>palés a retener</span></div><div><strong>${cold?'6':'1'}</strong><span>${cold?'lotes relacionados':'lote relacionado'}</span></div><div><strong>0</strong><span>acciones aplicadas</span></div></div><label class="field-label" for="review-note">Motivo de la decisión</label><textarea id="review-note" rows="2" maxlength="400">Pendiente de evaluación por Calidad. Registrar evidencias antes de decidir el destino del producto.</textarea><p class="hint">Rol de la demo: Responsable de Calidad. No hay autenticación de usuarios en esta simulación.</p><div class="actions"><button class="primary" data-action="approve">Aprobar retención simulada</button><button class="danger-button" data-action="reject">Rechazar propuesta</button></div><p class="hint">La aprobación solo cambia este escenario. No escribe en SAP ni en el almacén.</p></section>`}
function resultPanel(r){return `<section class="card padded"><div class="eyebrow">EXPEDIENTE / ${r.id}</div><h2 class="success-heading">${r.kind==='cold'?'38 palés retenidos en la simulación':'2 palés retenidos en la simulación'}</h2><p>Decisión de Calidad registrada. El expediente queda abierto para investigación.</p><div class="facts"><div><span>Estado de la investigación</span><strong>Abierta · causa no confirmada</strong></div><div><span>Aprobación</span><strong>Responsable de Calidad · demo</strong></div><div><span>Hipótesis a contrastar</span><strong>${r.kind==='cold'?'Solape de desescarche y puerta abierta':'Desgaste de malla DP-2'}</strong></div><div><span>Siguiente revisión</span><strong>${r.kind==='cold'?'Temperatura de producto y evaluación':'Muestra del cliente e inspección DP-2'}</strong></div></div><div class="banner">${r.kind==='cold'?'Los palés fuera de C-07 no se han retenido por esta alarma. Su relación con los lotes queda documentada.':'Los 20 palés expedidos no figuran como bloqueados. Calidad debe evaluar su alcance y la comunicación al cliente.'}</div>${r.kind==='complaint'?'<button class="secondary" style="margin-top:18px" data-action="reply-draft">Ver borrador de respuesta</button>':''}<div class="actions"><button class="primary" data-action="download-report">Descargar expediente</button><button class="secondary" data-action="${r.kind==='cold'?'open-case':'open-knowledge'}">${r.kind==='cold'?'Probar reclamación':'Consultar procedimientos'}</button></div><p class="hint">Expediente HTML: se abre sin instalación y permite imprimir o guardar como PDF.</p></section>`}
function activeRun(){return S.view==='case'?S.complaint:S.run}
function decide(approved){const r=activeRun();if(!r||r.status!=='pending')return;const note=$('#review-note').value.trim();if(!note){toast('Añade el motivo de la decisión.');$('#review-note').focus();return}r.note=note;r.decision=approved?'approved':'rejected';r.status=approved?'approved':'rejected';logRun(r,`${approved?'Aprobación':'Rechazo'} del rol Responsable de Calidad (demo). Motivo: ${note}`);if(approved){logRun(r,`Retención simulada aplicada a ${r.kind==='cold'?'38 palés de C-07':'2 palés de SIL-3'}. No se ha contactado con sistemas externos.`);logRun(r,'Expediente de investigación preparado. Causa raíz y acciones correctivas pendientes de validar.')}else logRun(r,'Ejecución detenida sin retención.');render();scrollExecution()}
function lotModal(id){const l=DEMO_DATA.lots.find(l=>l.id===id);if(!l)return;modal('Trazabilidad · '+id,`<span class="badge info">Genealogía sintética</span><p><b>${esc(l.product)}</b> · ${l.produced} palés producidos.</p><h3>Hacia atrás · origen y transformación</h3><ol class="timeline"><li><time>Cosecha · ${l.origin.harvest}</time>Agricultor ${l.origin.grower} · parcelas ${l.origin.parcels.join(', ')}.</li><li><time>Recepción</time>${l.origin.intake} · línea ${l.origin.line}.</li>${l.origin.bulk?`<li><time>Granel intermedio</time>${l.origin.bulk} · se conserva el vínculo con el reenvasado.</li>`:''}<li><time>Producción · ${l.production}</time>${l.route.join(' → ')} · línea ${l.line}.</li></ol><h3 style="margin-top:20px">Hacia delante · balance de palés</h3><table class="trace-table"><thead><tr><th>Destino</th><th>Palés</th><th>Alcance</th></tr></thead><tbody>${l.allocations.map(a=>`<tr><td>${a.where}</td><td>${a.count}</td><td>${a.where==='C-07'?'Expuestos al episodio':a.shipped?'Ya expedidos; evaluar relación':'Fuera de la cámara C-07'}</td></tr>`).join('')}</tbody></table><div class="banner">${l.allocations.map(a=>a.count).join(' + ')} = ${l.produced} palés. ${l.exposed?'La propuesta de cadena de frío afecta a '+l.exposed+' palés de este lote.':'La reclamación se evalúa por separado de la alarma de frío.'}</div>${l.components?.length?'<h3 style="margin-top:20px">Origen de la mezcla</h3><ul>'+l.components.map(c=>'<li><b>'+esc(c.name)+' · '+c.share+' %</b><br>'+c.bulk+' · '+c.grower+' · '+c.intake+'</li>').join('')+'</ul>':''}${l.maintenance.length?'<p><b>Evidencia de mantenimiento:</b> OT-26-07415, 18/08/2026: desgaste de malla de DP-2 anotado. Es una hipótesis de investigación, no una causa raíz confirmada.</p>':''}`)}
function caseView(){return head('CALIDAD / ATENCIÓN AL CLIENTE','Del correo al expediente.','Extrae el lote, conecta las evidencias y prepara la revisión de Calidad.')+`<div class="split"><section class="card padded"><div style="display:flex;justify-content:space-between;gap:12px"><h2>Correo de un cliente británico</h2><span class="badge info">Ejemplo ficticio</span></div><label class="field-label" for="complaint-email">Email de la reclamación</label><textarea id="complaint-email" rows="15" maxlength="6000" style="font-size:13px">${esc(S.email||S.complaint?.email||exampleEmail)}</textarea><div class="actions"><button class="primary full" data-action="analyze-case" ${S.complaint?.status==='running'?'disabled':''}>Analizar reclamación</button><button class="text-button" data-action="reset-email">Restaurar ejemplo</button></div><p class="hint">La demo reconoce el lote y el objeto descritos en este ejemplo. No pegues información real o confidencial.</p></section><section class="card padded"><div class="eyebrow">RECLAMACIÓN UKC-44718</div><h2>${S.complaint?'Información estructurada':'Una investigación que empieza con contexto'}</h2>${S.complaint?`<div class="facts"><div><span>Producto</span><strong>Garden Peas 1kg</strong></div><div><span>Lote reconocido</span><strong>L26-231-FUS-GUI-01</strong></div><div><span>Motivo declarado</span><strong>Piedra · aprox. 8 mm</strong></div><div><span>Petición del cliente</span><strong>Informe en 5 días hábiles</strong></div><div><span>Stock disponible</span><strong>2 palés · SIL-3</strong></div><div><span>Ya expedidos</span><strong>20 palés · 2 expediciones</strong></div></div><div class="banner warning"><b>Hipótesis, no conclusión:</b> una nota de mantenimiento registra desgaste en la malla de DP-2. Hay que contrastarlo con la muestra y la inspección.</div><button class="secondary" style="margin-top:18px" data-lot="L26-231-FUS-GUI-01">Explorar trazabilidad del lote</button>`:`<p>El correo llega en inglés. El equipo trabaja en español. El proceso necesita conservar el lote, distinguir hechos de hipótesis y preparar una respuesta revisable.</p><div class="workflow-board" style="margin-top:20px;border-radius:8px">${nodes('complaint')}</div>`}</section></div>${S.complaint?execution(S.complaint):''}`}
function analyzeCase(override){if(S.complaint?.status==='running')return;const email=override||$('#complaint-email')?.value||exampleEmail;S.email=email;const found=email.match(/L\d{2}-\d{3}-[A-Z]{3}-[A-Z]{3}-\d{2}/g)||[];if(found.length!==1||found[0]!=='L26-231-FUS-GUI-01'||!/stone|piedra/i.test(email)||!/8\s*mm/i.test(email)||!/UKC-44718/.test(email)||!/five working days|5\s*d[ií]as/i.test(email)||!/Garden Peas/i.test(email)){S.complaint=null;render();modal('Falta un escenario reconocido','<p>Esta demostración no puede investigar ese correo con los datos disponibles. Utiliza el ejemplo sintético de UKC-44718 o restaura el ejemplo. No se ha generado un expediente ni una retención para este texto.</p>');return}S.complaint={kind:'complaint',status:'pending',id:'SIM-NC-002',email,audit:[],decision:null};logRun(S.complaint,'Correo sintético reconocido: UKC-44718, lote L26-231-FUS-GUI-01, piedra de aproximadamente 8 mm.');logRun(S.complaint,'Traza recuperada: 22 palés producidos; 20 expedidos y 2 disponibles en SIL-3.');logRun(S.complaint,'Nota de DP-2 localizada. Hipótesis pendiente de confirmación.');logRun(S.complaint,'Retención propuesta para 2 palés. Pendiente de aprobación de Calidad.');render();scrollExecution()}
const documents={cold:{id:'PNT-DEMO-012',title:'Evaluación de una excursión de temperatura',version:'1.0 · 29/09/2026',text:'En este escenario de demostración, una temperatura de aire superior a −18 °C durante más de 15 minutos genera una propuesta de retención de los palés presentes en la cámara. El Responsable de Calidad revisa la evidencia y aprueba o rechaza la propuesta. La temperatura de aire no demuestra la temperatura de producto ni permite concluir su aptitud. Calidad debe evaluar el producto conforme al procedimiento real de la planta. Los umbrales de este documento son ficticios y no constituyen instrucciones de seguridad alimentaria.'},release:{id:'PNT-DEMO-015',title:'Retención y liberación de lotes',version:'1.0 · 29/09/2026',text:'En esta demostración, el rol Responsable de Calidad revisa cada propuesta de retención. La aprobación registra el alcance, los palés y el motivo; el rechazo detiene la ejecución sin retener producto. La liberación requiere una decisión de Calidad basada en evidencias y no está automatizada en la demo. Una retención del stock disponible no equivale a una retirada de producto ya expedido. En producción se aplican los permisos, procedimientos y requisitos aprobados por la organización.'},complaint:{id:'PNT-DEMO-020',title:'Reclamaciones e investigación de causa',version:'1.0 · 29/09/2026',text:'La investigación del ejemplo recoge la referencia del cliente, el lote, el defecto declarado y la petición de respuesta. Se conserva la trazabilidad hacia origen y expediciones. Las notas de mantenimiento son indicios: la causa raíz no se confirma hasta contrastarla con evidencia. Calidad revisa el borrador de investigación y el mensaje al cliente antes de cualquier envío. El ejemplo solicita un informe en cinco días hábiles; no es un plazo general ni un compromiso real.'}};
function knowledge(){return head('CONOCIMIENTO / RESPUESTAS VERIFICABLES','Una respuesta. Su fuente.','Consulta los procedimientos ficticios que gobiernan esta demostración.')+`<div class="split"><section class="card padded"><h2>Biblioteca de Calidad</h2><p>Tres documentos preparados para el escenario. Puedes leerlos completos.</p><div class="knowledge-cards">${Object.entries(documents).map(([k,d])=>`<button class="doc-card" data-doc="${k}"><strong>${d.id}</strong><p>${d.title}</p><p>Versión ${d.version} · Ficticio</p></button>`).join('')}</div><div class="banner warning">Documentos ilustrativos. Los procedimientos vigentes de la planta serían la fuente en un piloto.</div></section><section class="card padded"><h2>Pregunta al asistente de Calidad</h2><label class="field-label" for="question">Tu pregunta</label><textarea id="question" rows="3" maxlength="600" placeholder="¿Quién puede liberar un lote retenido?">${esc(S.question)}</textarea><div class="chips"><button class="chip" data-q="¿Quién puede liberar un lote retenido?">Liberación de lotes</button><button class="chip" data-q="¿Qué ocurre si una cámara supera el umbral de temperatura?">Alarma de temperatura</button><button class="chip" data-q="¿Cómo se confirma la causa de una reclamación?">Causa raíz</button></div><button class="primary" data-action="ask">Consultar fuentes</button>${S.answer?`<hr class="divider"><div class="eyebrow">${S.answer.doc?'RESPUESTA BASADA EN LA BIBLIOTECA':'SIN EVIDENCIA SUFICIENTE'}</div><div class="answer">${esc(S.answer.text)} ${S.answer.doc?`<button class="citation" data-doc="${S.answer.doc}">[1] Abrir fuente</button>`:''}</div>${S.answer.doc?`<button class="doc-card" data-doc="${S.answer.doc}"><strong>[1] ${documents[S.answer.doc].id}</strong><p>${documents[S.answer.doc].title}</p></button>`:'<div class="banner warning">No se ha inventado una respuesta. Reformula la consulta sobre uno de los tres procedimientos o aporta una fuente validada en el piloto.</div>'}`:'<div class="banner">Prueba también una pregunta fuera de la biblioteca: el asistente debe reconocer cuándo le falta información.</div>'}<p class="hint">Respuestas predefinidas según el tema, con fuente inspeccionable. Esta página no consulta un modelo de IA.</p></section></div>`}
function ask(q){S.question=q||$('#question').value.trim();if(!S.question){toast('Escribe una pregunta.');return}const p=normalize(S.question);const unknown=/listeria|alergen|precio|cliente|factura|normativa|ley|legal|salario|contrase|receta|vida util|mercadona/.test(p);let doc=null,text='No encuentro evidencia suficiente en los tres procedimientos de esta demo para responder a esa pregunta.';if(!unknown&&/liber|quien.*reten|quien.*bloque/.test(p)){doc='release';text='La liberación corresponde al Responsable de Calidad y exige una decisión basada en evidencias. Esta demo no libera producto automáticamente. Retener stock disponible tampoco equivale a retirar producto ya expedido.'}else if(!unknown&&/temperatura|camara|frio|umbral/.test(p)){doc='cold';text='La regla del ejemplo propone retener los palés de la cámara si el aire supera −18 °C durante más de 15 minutos. Calidad debe revisar y aprobar. La lectura del aire no permite determinar por sí sola la temperatura o aptitud del producto.'}else if(!unknown&&/causa|reclamacion|8d|investigacion/.test(p)){doc='complaint';text='El equipo recoge la referencia, el lote y el defecto, y recupera la trazabilidad. Las notas de mantenimiento son indicios. Calidad debe contrastar la evidencia antes de confirmar una causa y revisar el borrador antes de responder al cliente.'}S.answer={doc,text};render()}
function platform(){return head('PRODIGY / DE LA DEMO AL PILOTO','La plataforma detrás del proceso.','Agentes, conocimiento y controles para coordinar trabajo entre sistemas.')+`<section class="platform-band"><div class="eyebrow" style="color:var(--mint)">PROPUESTA PARA CONGELADOS DE NAVARRA</div><h2>Reunir la información. Preparar la acción.<br>Mantener la decisión bajo control.</h2><p>Una capa de agentes sobre los sistemas que ya utilizáis, con pasos visibles, respuestas con fuentes y puntos de aprobación definidos por vuestro equipo.</p></section><div class="architecture"><div><b>Sistemas y documentos</b><small>ERP · producción · almacén<br>Procedimientos de Calidad</small></div><div class="core"><b>Prodigy</b><small>Orquestación de agentes y Routines<br>Conocimiento · permisos · trazas · aprobación</small></div><div><b>Personas que deciden</b><small>Calidad · jefe de turno · logística<br>Propuesta revisada y evidencia disponible</small></div></div><div class="pillars"><article class="card pillar"><div class="n">01 / FLUJOS REUTILIZABLES</div><h3>Del caso aislado al proceso</h3><p>Las Routines ordenan capacidades en una secuencia. El equipo puede revisar el plan y reutilizarlo en casos similares.</p></article><article class="card pillar"><div class="n">02 / GOBIERNO</div><h3>Permisos y evidencia</h3><p>La plataforma incorpora roles, trazas y puntos de aprobación. En el piloto se define qué acciones puede hacer cada agente.</p></article><article class="card pillar"><div class="n">03 / ELECCIÓN TECNOLÓGICA</div><h3>Despliegue y modelos</h3><p>Prodigy admite despliegue en infraestructura del cliente y un catálogo de modelos. El alojamiento y los flujos de datos se acuerdan con Sistemas.</p></article></div><div class="section-title"><h2>Qué estás viendo y qué construiríamos</h2></div><div class="card table-scroll"><table class="trace-table"><thead><tr><th>Base de Prodigy</th><th>Esta demostración web</th><th>Trabajo del piloto</th></tr></thead><tbody><tr><td>Routines y compositor visual</td><td>Generador por reglas para tres escenarios</td><td>Generación con LLM y validación en el runtime</td></tr><tr><td>Trazas y puntos de aprobación</td><td>Decisiones y registro de esta sesión</td><td>SSO, roles, auditoría persistente y pruebas</td></tr><tr><td>Conocimiento con fuentes</td><td>Tres documentos ficticios y respuestas preparadas</td><td>Procedimientos vigentes, permisos y evaluación</td></tr><tr><td>Arquitectura ampliable por capacidades</td><td>Datos y acciones sintéticos en el navegador</td><td>Conectores a los sistemas acordados con CN</td></tr></tbody></table></div><p class="review-note">La web es un demostrador conceptual independiente: no ejecuta el backend de Prodigy ni incluye su código privado. La generación desde texto es una extensión propuesta para el caso; no se presenta como función de serie. Ninguna acción se transmite a una planta.</p><div class="section-title"><h2>Un piloto medible</h2><span class="badge neutral">PROPUESTA A VALIDAR</span></div><div class="grid-main"><section class="card padded"><h3>Un caso, una planta, Calidad y Sistemas</h3><p>Como punto de partida: 6–8 semanas, sujeto a accesos y alcance. Leer uno o dos sistemas, preparar borradores y comparar contra casos históricos.</p><div class="pillars" style="gap:15px"><div><div class="eyebrow">SEM. 1–2</div><p><b>Medir y conectar</b><br>Datos, permisos y línea base.</p></div><div><div class="eyebrow">SEM. 3–5</div><p><b>Construir y contrastar</b><br>Casos históricos y revisión.</p></div><div><div class="eyebrow">SEM. 6–8</div><p><b>Evaluar</b><br>Tiempo, exactitud y aceptación.</p></div></div><div class="banner">Criterios a pactar: coincidencia de lotes y palés, calidad de citas, tiempo hasta el borrador y ausencia de acciones sin autorización.</div></section><section class="card padded"><div class="eyebrow">CALCULADORA DE HIPÓTESIS</div><h3>Tiempo potencial recuperable</h3><label class="field-label" for="roi-cases">Casos al mes</label><input id="roi-cases" type="number" min="0" max="10000" value="${S.roi.cases}" data-roi="cases"><div class="rules-row"><div><label class="field-label" for="roi-before">Minutos actuales</label><input id="roi-before" type="number" min="0" max="10000" value="${S.roi.before}" data-roi="before"></div><div><label class="field-label" for="roi-after">Minutos objetivo</label><input id="roi-after" type="number" min="0" max="10000" value="${S.roi.after}" data-roi="after"></div></div><div class="banner"><strong id="roi-result" style="font-size:28px">${fmt(S.roi.cases*(S.roi.before-S.roi.after)/60)} h/mes</strong><br><span id="roi-description">Casos × diferencia de tiempo / 60.</span></div><p class="hint">Supuestos editables, no resultados medidos. No estima ahorros económicos ni retorno de inversión.</p></section></div><div class="section-title"><h2>Contexto público de Congelados de Navarra</h2></div><section class="card padded"><p style="margin-top:0">Su historia corporativa recoge la implantación de SAP. Mecalux documenta Easy WMS en Fustiñana y Planning Manufacturing, un proyecto de planificación con Opcenter. Son referencias públicas; el inventario y los accesos actuales se confirmarían con Sistemas.</p><div class="sources"><a href="https://www.congeladosnavarra.com/es/congelados-navarra/historia" target="_blank" rel="noopener">Congelados de Navarra · Historia y SAP</a><a href="https://www.mecalux.es/casos-practicos/almacen-de-congelados-navarra" target="_blank" rel="noopener">Mecalux · Automatización logística y Easy WMS en Fustiñana</a><a href="https://www.planningmanufacturing.com/casos-de-exito/caso-de-exito-congelados-navarra" target="_blank" rel="noopener">Planning Manufacturing · Planificación con Opcenter</a></div><p class="hint">Fuentes consultadas el 29/09/2026. Los incidentes de esta demo no describen hechos de Congelados de Navarra.</p></section><div class="section-title"><h2>Preguntas que conviene resolver juntos</h2></div><details class="faq"><summary>¿Prodigy se integra ya con nuestros sistemas?</summary><p>La demo no incluye conectores activos a SAP, MES o WMS. La integración se diseña y verifica en el piloto, empezando por acceso de lectura y un caso acotado.</p></details><details class="faq"><summary>¿Dónde quedarían los datos?</summary><p>El diseño permite alojar Prodigy en la infraestructura acordada. Los datos que se envían al modelo dependen del proveedor y la configuración elegidos. Sistemas debe aprobar esa arquitectura.</p></details><details class="faq"><summary>¿Puede bloquear o liberar producto por su cuenta?</summary><p>En el caso propuesto, cualquier retención requiere una aprobación explícita de Calidad. La liberación queda fuera de esta automatización. La demo solo modifica datos ficticios en tu navegador.</p></details><details class="faq"><summary>¿Qué proponemos como siguiente paso?</summary><p>Un taller con Calidad y Sistemas para elegir el primer caso, revisar los datos accesibles y fijar los criterios de éxito. Licencia, operación y precio se concretan en la propuesta comercial.</p></details>`}
function dailyReport(){modal('Parte diario · Fustiñana',`<span class="badge info">11 equipos · datos sintéticos</span><p>4 lecturas críticas y 3 avisos según reglas de este escenario. Este parte no sustituye las alarmas ni los procedimientos de planta.</p><div class="table-scroll"><table class="trace-table"><thead><tr><th>Equipo</th><th>Lectura</th><th>Ref.</th><th>Prioridad</th></tr></thead><tbody>${DEMO_DATA.machines.map(machineRow).join('')}</tbody></table></div><p>El jefe de turno revisa las prioridades y asigna la evaluación. No se ha creado ningún ticket externo.</p>`)}
function replyDraft(){modal('Borrador de respuesta · sin enviar',`<span class="badge amber">Revisión obligatoria de Calidad</span><div class="email" style="margin-top:18px">Dear Customer Quality Team,\n\nThank you for reporting complaint UKC-44718 regarding batch L26-231-FUS-GUI-01.\n\nIn this demonstration scenario, we have opened an investigation and identified the related production and dispatch records. The two pallets remaining in stock are on a simulated quality hold. The scope of the dispatched product is under review.\n\nWe will assess the returned sample and the relevant production and maintenance evidence before confirming a root cause. Our Quality team will review the findings and agree the response timing with you.\n\nKind regards,\nQuality Team\n\nDRAFT — FICTIONAL DEMONSTRATION — NOT SENT</div><p>La investigación sigue abierta. Este texto no confirma una causa ni comunica una retirada.</p>`)}
function download(name,content,type){const blob=new Blob([content],{type});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function report(){const r=activeRun();if(!r||r.status!=='approved')return;const html=`<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Expediente ${r.id} · DEMO</title><style>body{font:16px/1.65 system-ui;color:#153546;max-width:850px;margin:40px auto;padding:25px}h1{font-size:32px}h2{margin-top:30px}p{margin:10px 0}.badge{padding:12px;background:#e5f5ef}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:12px;text-align:left;border-bottom:1px solid #ddd}small{display:block;color:#567}button{background:#fff;border:0;color:#175c58;text-align:left}li{margin:12px 0}.print{background:#16313f;color:#fff;padding:10px 15px;border:0;border-radius:5px;cursor:pointer}@media print{.print{display:none}body{margin:0}}</style><button class="print" onclick="window.print()">Imprimir / Guardar como PDF</button><h1>Expediente de investigación</h1><div class="badge">${r.id} · Datos ficticios · Acciones simuladas · Investigación abierta</div><h2>1. Hechos del escenario</h2><p>${r.kind==='cold'?`Alarma C-07. Temperatura de aire máxima: −13,9 °C. Regla configurada: más de ${r.duration} minutos por encima de ${r.threshold} °C. Exposición calculada: ${r.exposure} minutos (muestreo de 5 min). Alcance: 38 palés, 6 lotes.`:'Reclamación UKC-44718, lote L26-231-FUS-GUI-01: el cliente declara una piedra de aproximadamente 8 mm. 22 palés producidos, 20 expedidos y 2 disponibles en SIL-3.'}</p><h2>2. Alcance de la retención</h2>${lotTable(r.kind).replace(/<button[^>]*>/g,'<span>').replace(/<\/button>/g,'</span>')}<h2>3. Decisión humana</h2><p>Rol: Responsable de Calidad (simulado). Decisión: aprobar la retención simulada de ${r.kind==='cold'?'38':'2'} palés. Motivo: ${esc(r.note)}.</p><h2>4. Hipótesis y tareas pendientes</h2><p>${r.kind==='cold'?'Solape de desescarche EV-07 y puerta P-07 abierta. Hipótesis por contrastar con registros y evaluación de temperatura de producto.':'Desgaste de la malla DP-2, anotado en OT-26-07415. Hipótesis por contrastar con muestra e inspección.'}</p><p>Causa raíz pendiente. Acciones correctivas, validación de eficacia y cierre pendientes de Calidad. Este expediente no representa un 8D completo ni una conclusión de seguridad alimentaria.</p><h2>5. Registro de ejecución</h2><ol>${r.audit.map(a=>`<li><b>${a.time}</b> ${esc(a.message)}</li>`).join('')}</ol><p>Preparado con el demostrador conceptual de Prodigy. Ningún mensaje enviado ni modificación en sistemas de producción.</p></html>`;download(`expediente-${r.id}.html`,html,'text/html');toast('Expediente descargado. Ábrelo para imprimir o guardar como PDF.')}
function reset(){modal('Reiniciar demostración','<p>Se borrarán los workflows, decisiones y consultas de esta sesión. Los datos ficticios volverán al inicio.</p><div class="actions"><button class="primary" data-action="confirm-reset">Reiniciar</button><button class="secondary" data-action="close-modal">Cancelar</button></div>')}
function performReset(){runToken++;const guide=S.guide;S={view:'operations',guide,prompt:coldPrompt,draft:null,workflow:null,run:null,complaint:null,question:'',answer:null,roi:{cases:40,before:45,after:15}};$('#modal').close();go('operations');toast('Demo reiniciada. Lista para una nueva presentación.')}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.nav){go(b.dataset.nav);return}if(b.dataset.lot){lotModal(b.dataset.lot);return}if(b.dataset.doc){const d=documents[b.dataset.doc];modal(d.id,`<span class="badge info">Procedimiento ficticio · versión ${d.version}</span><h3 style="margin-top:20px">${d.title}</h3><p>${d.text}</p>`);return}if(b.dataset.q){ask(b.dataset.q);return}if(b.dataset.example){S.prompt={cold:coldPrompt,complaint:complaintPrompt,daily:dailyPrompt}[b.dataset.example];$('#workflow-prompt').value=S.prompt;toast('Ejemplo cargado. Pulsa Generar workflow.');return}const a=b.dataset.action;const actions={'open-studio':()=>go('studio'),'open-case':()=>go('case'),'open-knowledge':()=>go('knowledge'),'generate':generate,'save-workflow':saveWorkflow,'run':runWorkflow,'approve':()=>decide(true),'reject':()=>decide(false),'close-modal':()=>$('#modal').close(),'analyze-case':()=>analyzeCase(),'reset-email':()=>{S.email=exampleEmail;$('#complaint-email').value=exampleEmail},'ask':()=>ask(),'daily-report':dailyReport,'download-report':report,'reply-draft':replyDraft,'retry':()=>{if(S.view==='case')analyzeCase(exampleEmail);else runWorkflow()},'toggle-guide':()=>{S.guide=!S.guide;render()},'confirm-reset':performReset,'download-audit':()=>{const r=activeRun();if(r)download(`registro-${r.id}.json`,JSON.stringify({simulation:true,incident:r.id,status:r.status,events:r.audit},null,2),'application/json')},'edit-workflow':()=>{if(S.run?.status==='running'||S.run?.status==='pending')return;S.run=null;render();window.scrollTo(0,0)},'export-workflow':()=>{if(S.workflow)download('workflow-prodigy-demo.json',JSON.stringify({simulation:true,runtime:'browser-demonstrator',...S.workflow,steps:steps[S.workflow.kind].map(s=>s[1]),requiresHumanApproval:S.workflow.kind!=='daily'},null,2),'application/json')}};actions[a]?.()});
document.addEventListener('input',e=>{if(e.target.id==='workflow-prompt')S.prompt=e.target.value;if(e.target.id==='complaint-email')S.email=e.target.value;if(e.target.dataset.roi){const val=Number(e.target.value);if(!Number.isFinite(val)||val<0||val>10000)return;S.roi[e.target.dataset.roi]=val;const hours=S.roi.cases*(S.roi.before-S.roi.after)/60;$('#roi-result').textContent=fmt(hours)+' h/mes';$('#roi-description').textContent=hours<0?'El objetivo aumenta el tiempo: revisa los supuestos.':'Casos × diferencia de tiempo / 60.'}});
$('#presenter').onclick=()=>{S.guide=!S.guide;render()};$('#reset').onclick=reset;$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('Usa la opción de pantalla completa de tu navegador.')}};
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('#modal').close()}});
window.addEventListener('hashchange',()=>{const v=location.hash.slice(1);if(titles[v]&&v!==S.view){S.view=v;render()}});
if(titles[location.hash.slice(1)])S.view=location.hash.slice(1);render();
function longestExposure(threshold){let current=0,best=0;for(const v of DEMO_DATA.temperature.slice(0,-1)){current=v>threshold?current+5:0;best=Math.max(best,current)}return best}
function liveStudio(w,r){return head('WORKFLOW STUDIO / EJECUCIÓN SIMULADA','De la señal a la decisión.','Cada paso deja evidencia. Calidad controla la retención.',`<button class="secondary" data-action="edit-workflow" ${['running','pending'].includes(r.status)?'disabled':''}>Volver al diseño</button>`)+`<section class="card live-workflow"><div class="card-head"><div><h2>${esc(w.name)}</h2><p>Regla guardada: más de ${w.minutes} minutos sobre ${w.temp} °C · C-07</p></div><span class="badge info">5 pasos</span></div><div class="workflow-live">${nodes(w.kind,r)}</div></section>`+execution(r)}
function execution(r){const stage=({running:'Reuniendo evidencias…',pending:'Propuesta lista para revisar',rejected:'Propuesta rechazada',approved:'Expediente preparado','no-trigger':'La regla no activa una retención'})[r.status];const badge=({running:'En curso',pending:'Espera aprobación',rejected:'Sin retención',approved:'Retención simulada','no-trigger':'Sin activación'})[r.status];const table=`<section class="card"><div class="card-head"><div><h2>${r.kind==='cold'?'Alcance · 38 palés en C-07':'Alcance · 22 palés del lote'}</h2><p>Abre un lote para consultar su origen y destinos.</p></div></div>${lotTable(r.kind)}<div class="padded" style="padding-top:8px"><p class="hint">${r.kind==='cold'?'La propuesta afecta solo al stock presente en la cámara durante el episodio. La traza mantiene separados los otros destinos.':'Solo quedan 2 palés disponibles en SIL-3. Los 20 expedidos requieren una evaluación separada.'}</p></div></section>`;let body='';if(r.status==='pending')body=`<div class="decision-layout"><div>${table}<div style="margin-top:20px">${audit(r)}</div></div>${approval(r)}</div>`;else if(r.status==='approved')body=`<div class="run-panel">${resultPanel(r)}${audit(r)}</div><details class="faq" style="margin-top:20px"><summary>Consultar los lotes del expediente</summary>${table}</details>`;else if(r.status==='rejected')body=`<div class="run-panel"><section class="card padded"><h2>Decisión registrada: rechazar</h2><p>La ejecución se ha detenido. No se ha aplicado ninguna retención.</p><div class="banner warning">Motivo: ${esc(r.note)}</div><p class="small-note">Calidad revisará la propuesta antes de una nueva ejecución.</p><button class="secondary" data-action="retry">Volver a ejecutar</button></section>${audit(r)}</div>`;else if(r.status==='no-trigger')body=`<div class="run-panel"><section class="card padded"><h2>Sin propuesta de retención</h2><div class="banner">${r.exposure} minutos consecutivos por encima de ${r.threshold} °C. La regla requiere más de ${r.duration} minutos. No se activa.</div><p>Vuelve al diseño para ajustar la regla y probar de nuevo.</p></section>${audit(r)}</div>`;else body=`<div class="run-panel"><section class="card padded"><h2>Consultando las evidencias</h2><p>Lecturas de la cámara, inventario y genealogía de los lotes.</p><div class="progress-track"><span style="width:${r.step===0?'25':'60'}%"></span></div></section>${audit(r)}</div>`;return `<div class="execution" id="execution"><div class="section-title"><div><div class="eyebrow">EJECUCIÓN / ${r.id}</div><h2>${stage}</h2></div><span class="badge ${r.status==='pending'?'amber':r.status==='rejected'?'danger':'good'}">${badge}</span></div>${body}</div>`}
